package com.meridianbank.dto;

import com.fasterxml.jackson.annotation.JsonFormat;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.List;

/**
 * DTO for Oracle Text document search requests and results.
 *
 * <p>Searches use Oracle Text {@code CONTAINS()} function and {@code SCORE()} function.
 * Highlights are generated by {@code CTX_DOC.HIGHLIGHT}.
 */
public class DocumentSearchDTO {

    // Search parameters
    /** Oracle Text CONTAINS() query string — supports operators: AND, OR, NOT, NEAR, etc. */
    private String searchQuery;
    private Long customerId;
    private String category;

    @JsonFormat(pattern = "yyyy-MM-dd")
    private LocalDate indexedAfter;

    @JsonFormat(pattern = "yyyy-MM-dd")
    private LocalDate indexedBefore;

    // Single document result
    private Long documentId;
    private String title;
    private String category2;
    private Long documentCustomerId;

    /** Oracle Text SCORE() relevance score (0–100). */
    private Integer relevanceScore;

    /** Highlighted excerpt from Oracle CTX_DOC.HIGHLIGHT. */
    private String highlightedExcerpt;

    @JsonFormat(pattern = "yyyy-MM-dd")
    private LocalDate indexedDate;

    @JsonFormat(pattern = "yyyy-MM-dd'T'HH:mm:ss")
    private LocalDateTime createdDate;

    // List result
    private List<DocumentSearchDTO> results;
    private Integer totalCount;
    private Integer page;
    private Integer pageSize;
    public DocumentSearchDTO() {
    }


    public String getSearchQuery() {
        return searchQuery;
    }

    public void setSearchQuery(String searchQuery) {
        this.searchQuery = searchQuery;
    }

    public Long getCustomerId() {
        return customerId;
    }

    public void setCustomerId(Long customerId) {
        this.customerId = customerId;
    }

    public String getCategory() {
        return category;
    }

    public void setCategory(String category) {
        this.category = category;
    }

    public LocalDate getIndexedAfter() {
        return indexedAfter;
    }

    public void setIndexedAfter(LocalDate indexedAfter) {
        this.indexedAfter = indexedAfter;
    }

    public LocalDate getIndexedBefore() {
        return indexedBefore;
    }

    public void setIndexedBefore(LocalDate indexedBefore) {
        this.indexedBefore = indexedBefore;
    }

    public Long getDocumentId() {
        return documentId;
    }

    public void setDocumentId(Long documentId) {
        this.documentId = documentId;
    }

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getCategory2() {
        return category2;
    }

    public void setCategory2(String category2) {
        this.category2 = category2;
    }

    public Long getDocumentCustomerId() {
        return documentCustomerId;
    }

    public void setDocumentCustomerId(Long documentCustomerId) {
        this.documentCustomerId = documentCustomerId;
    }

    public Integer getRelevanceScore() {
        return relevanceScore;
    }

    public void setRelevanceScore(Integer relevanceScore) {
        this.relevanceScore = relevanceScore;
    }

    public String getHighlightedExcerpt() {
        return highlightedExcerpt;
    }

    public void setHighlightedExcerpt(String highlightedExcerpt) {
        this.highlightedExcerpt = highlightedExcerpt;
    }

    public LocalDate getIndexedDate() {
        return indexedDate;
    }

    public void setIndexedDate(LocalDate indexedDate) {
        this.indexedDate = indexedDate;
    }

    public LocalDateTime getCreatedDate() {
        return createdDate;
    }

    public void setCreatedDate(LocalDateTime createdDate) {
        this.createdDate = createdDate;
    }

    public List<DocumentSearchDTO> getResults() {
        return results;
    }

    public void setResults(List<DocumentSearchDTO> results) {
        this.results = results;
    }

    public Integer getTotalCount() {
        return totalCount;
    }

    public void setTotalCount(Integer totalCount) {
        this.totalCount = totalCount;
    }

    public Integer getPage() {
        return page;
    }

    public void setPage(Integer page) {
        this.page = page;
    }

    public Integer getPageSize() {
        return pageSize;
    }

    public void setPageSize(Integer pageSize) {
        this.pageSize = pageSize;
    }

}
